<script setup lang="ts">
import * as BoxunExperimentalReportApi from './BoxunExperimentalReportApi'

type BoxunExperimentalReportFormData = Parameters<typeof BoxunExperimentalReportApi.createBoxunExperimentalReport>[0]
type EntityId = string | number


defineOptions({ name: 'BoxunExperimentalReportForm' })

const emit = defineEmits<{ success: [] }>()
const message = useMessage()
const { t } = useI18n()
const dialogVisible = ref(false)
const dialogTitle = ref('')
const formLoading = ref(false)
const formType = ref<'create' | 'update'>('create')
const editingId = ref<EntityId>()
const formRef = ref()
const initialFormData = () => ({
  wtdSampleId: '',
  projectId: '',
  sampleId: '',
  commissionNumber: '',
  reportNumber: '',
  projectName: '',
  projectNumber: '',
  engineeringLocation: '',
  sampleNumber: '',
  sampleName: '',
  sampleName4bg: '',
  entrustingUnit: '',
  sgUnit: '',
  jsUnit: '',
  witnessUnit: '',
  witness: '',
  principal: '',
  sampleSender: '',
  entrustmentDate: undefined,
  testDate: undefined,
  reportDate: undefined,
  productionDate: undefined,
  makeDate: undefined,
  representativeQuantity: '',
  representativeBatch: '',
  model: '',
  type: '',
  strengthGrade: '',
  testMethod: '',
  detectionCategory: '',
  description: '',
  manufacturer: '',
  qualityLevel: '',
  sampleQuantity: '',
  attachmentUrl: ''
}) as BoxunExperimentalReportFormData
const formData = ref(initialFormData())
const formRules = reactive({

})






const open = async (type: 'create' | 'update', id?: EntityId, defaults?: Partial<BoxunExperimentalReportFormData>) => {

  formType.value = type
  editingId.value = id

  dialogTitle.value = type === 'create' ? '新增试验报告' : '修改试验报告'
  formData.value = { ...initialFormData(), ...defaults }
  formLoading.value = true
  dialogVisible.value = true
  try {


    if (id !== undefined) {
      formData.value = { ...initialFormData(), ...await BoxunExperimentalReportApi.getBoxunExperimentalReport(id) }

    }


  } finally {
    formLoading.value = false
    await nextTick()
    formRef.value?.clearValidate()

  }
}
defineExpose({ open })


const submitForm = async () => {
  if (formLoading.value) return



  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) {

    return
  }
  const inputFields = formType.value === 'create' ? ['wtdSampleId', 'projectId', 'sampleId', 'commissionNumber', 'reportNumber', 'projectName', 'projectNumber', 'engineeringLocation', 'sampleNumber', 'sampleName', 'sampleName4bg', 'entrustingUnit', 'sgUnit', 'jsUnit', 'witnessUnit', 'witness', 'principal', 'sampleSender', 'entrustmentDate', 'testDate', 'reportDate', 'productionDate', 'makeDate', 'representativeQuantity', 'representativeBatch', 'model', 'type', 'strengthGrade', 'testMethod', 'detectionCategory', 'description', 'manufacturer', 'qualityLevel', 'sampleQuantity', 'attachmentUrl'] : ['id', 'wtdSampleId', 'projectId', 'sampleId', 'commissionNumber', 'reportNumber', 'projectName', 'projectNumber', 'engineeringLocation', 'sampleNumber', 'sampleName', 'sampleName4bg', 'entrustingUnit', 'sgUnit', 'jsUnit', 'witnessUnit', 'witness', 'principal', 'sampleSender', 'entrustmentDate', 'testDate', 'reportDate', 'productionDate', 'makeDate', 'representativeQuantity', 'representativeBatch', 'model', 'type', 'strengthGrade', 'testMethod', 'detectionCategory', 'description', 'manufacturer', 'qualityLevel', 'sampleQuantity', 'attachmentUrl']
  const input = Object.fromEntries(inputFields.map((key) => [key, formData.value[key]]))
  if ('entrustmentDate' in input) input.entrustmentDate = formData.value.entrustmentDate ? String(formData.value.entrustmentDate).replace(' ', 'T') : null
  if ('testDate' in input) input.testDate = formData.value.testDate ? String(formData.value.testDate).replace(' ', 'T') : null
  if ('reportDate' in input) input.reportDate = formData.value.reportDate ? String(formData.value.reportDate).replace(' ', 'T') : null
  if ('productionDate' in input) input.productionDate = formData.value.productionDate ? String(formData.value.productionDate).replace(' ', 'T') : null
  if ('makeDate' in input) input.makeDate = formData.value.makeDate ? String(formData.value.makeDate).replace(' ', 'T') : null
  formLoading.value = true
  try {
    if (formType.value === 'create') {
      await BoxunExperimentalReportApi.createBoxunExperimentalReport(input)
      message.success(t('common.createSuccess'))
    } else {
      await BoxunExperimentalReportApi.updateBoxunExperimentalReport(input)
      message.success(t('common.updateSuccess'))
    }
    dialogVisible.value = false
    emit('success')
  } finally {
    formLoading.value = false
  }
